import { Router } from 'express';
import fs from 'fs/promises';
import path from 'path';
import {
  isPathStrictlyInsideRoot,
  resolveRealPathWithinRoot,
} from '../../utils/pathContainment';

export const createStaticPreviewRoutes = (canonicalRoot: string): Router => {
  const router = Router();
  router.get(/.*/, async (req, res) => {
    try {
      const relative = decodeURIComponent(req.path).replace(/^\/+/, '');
      const filename = path.resolve(canonicalRoot, relative);
      const canonicalFile = isPathStrictlyInsideRoot(canonicalRoot, filename)
        ? await resolveRealPathWithinRoot({
            root: canonicalRoot,
            candidate: filename,
            containment: 'strict',
          })
        : null;
      if (!canonicalFile || !(await fs.stat(canonicalFile)).isFile()) {
        res.sendStatus(404);
        return;
      }
      res.setHeader('X-Content-Type-Options', 'nosniff');
      res
        .type(path.extname(canonicalFile))
        .send(await fs.readFile(canonicalFile));
    } catch {
      res.sendStatus(404);
    }
  });
  return router;
};
